const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function rejectsWith(fn, message) {
  let error;
  try { await fn(); } catch (e) { error = e; }
  assert.ok(error, `expected rejection matching ${message}`);
  assert.match(error.message, message);
  return error;
}

async function main() {
  // Repeated equal amount returns the original receipt and debits once.
  {
    const ledger = new Ledger();
    const acks = [];
    const service = new PaymentService(ledger, { acknowledge: async r => { acks.push(r); } });
    const first = await service.pay('shop', 'sale', 123);
    const second = await service.pay('shop', 'sale', 123);
    assert.equal(second, first);
    assert.deepEqual(first, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks.length, 2);
  }

  // Reusing tenant/key with another amount conflicts without a debit or ack.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    await service.pay('shop', 'sale', 123);
    await rejectsWith(() => service.pay('shop', 'sale', 124), /key conflict/);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks, 1);
  }

  // Scope is per tenant+key.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const a = await service.pay('a', 'k', 1);
    const b = await service.pay('b', 'k', 2);
    const c = await service.pay('a', 'k2', 3);
    assert.equal(new Set([a.id, b.id, c.id]).size, 3);
    assert.equal(ledger.entries.length, 3);
  }

  // Concurrent equal calls share one debit/receipt.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const [a, b, c] = await Promise.all([
      service.pay('shop', 'sale', 500),
      service.pay('shop', 'sale', 500),
      service.pay('shop', 'sale', 500),
    ]);
    assert.equal(a, b);
    assert.equal(b, c);
    assert.equal(ledger.entries.length, 1);
  }

  // Concurrent conflicting calls: one debit, one key conflict.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    const results = await Promise.allSettled([
      service.pay('shop', 'sale', 500),
      service.pay('shop', 'sale', 600),
    ]);
    assert.equal(results[0].status, 'fulfilled');
    assert.equal(results[1].status, 'rejected');
    assert.match(results[1].reason.message, /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }

  // Transient acks are retried with the same receipt up to `attempts` tries.
  {
    const ledger = new Ledger();
    const seen = [];
    const failures = [new Transient('one'), new Transient('two')];
    const service = new PaymentService(ledger, { acknowledge: async r => {
      seen.push(r);
      if (failures.length) throw failures.shift();
    } });
    const receipt = await service.pay('shop', 'sale', 700, 3);
    assert.equal(seen.length, 3);
    assert.equal(seen[0], receipt);
    assert.equal(seen[1], receipt);
    assert.equal(seen[2], receipt);
    assert.equal(ledger.entries.length, 1);
  }

  // Default attempts (3) retries transients.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => {
      acks++;
      if (acks < 3) throw new Transient('flaky');
    } });
    const receipt = await service.pay('t', 'k', 50);
    assert.equal(receipt.id, 1);
    assert.equal(acks, 3);
    assert.equal(ledger.entries.length, 1);
  }

  // Exhausted retries preserve the final Transient instance.
  {
    const ledger = new Ledger();
    const thrown = [];
    const service = new PaymentService(ledger, { acknowledge: async () => {
      const error = new Transient(`ack ${thrown.length + 1}`);
      thrown.push(error);
      throw error;
    } });
    const caught = await rejectsWith(() => service.pay('shop', 'sale', 800, 2), /ack 2/);
    assert.equal(caught, thrown[1]);
    assert.equal(thrown.length, 2);
    assert.equal(ledger.entries.length, 1);
  }

  // attempts = 1 means a single try.
  {
    const ledger = new Ledger();
    let acks = 0;
    const error = new Transient('single');
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; throw error; } });
    const caught = await rejectsWith(() => service.pay('t', 'k', 5, 1), /single/);
    assert.equal(caught, error);
    assert.equal(acks, 1);
  }

  // Non-Transient errors are never retried.
  {
    const ledger = new Ledger();
    let acks = 0;
    const failure = new Error('boom');
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; throw failure; } });
    const caught = await rejectsWith(() => service.pay('shop', 'sale', 900, 5), /boom/);
    assert.equal(caught, failure);
    assert.equal(acks, 1);
    assert.equal(ledger.entries.length, 1);
  }

  // A later retry can acknowledge the committed receipt from an earlier failure.
  {
    const ledger = new Ledger();
    let down = true;
    const seen = [];
    const service = new PaymentService(ledger, { acknowledge: async r => {
      seen.push(r);
      if (down) throw new Transient('down');
    } });
    await rejectsWith(() => service.pay('t', 'k', 42, 2), /down/);
    down = false;
    const receipt = await service.pay('t', 'k', 42, 2);
    assert.equal(receipt, seen[0]);
    assert.equal(seen[seen.length - 1], receipt);
    assert.equal(ledger.entries.length, 1);
  }

  // Invalid input is rejected before any ledger/transport action.
  {
    const ledger = new Ledger();
    let acks = 0;
    const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    const cases = [
      ['', 'k', 1, 1], ['t', '', 1, 1], [null, 'k', 1, 1], ['t', null, 1, 1],
      [123, 'k', 1, 1], ['t', 123, 1, 1],
      ['t', 'k', 0, 1], ['t', 'k', -5, 1], ['t', 'k', 1.5, 1], ['t', 'k', NaN, 1],
      ['t', 'k', Infinity, 1], ['t', 'k', '10', 1],
      ['t', 'k', 10, 0], ['t', 'k', 10, 6], ['t', 'k', 10, 2.5], ['t', 'k', 10, '3'], ['t', 'k', 10, null],
    ];
    for (const args of cases) {
      await rejectsWith(() => service.pay(...args), /invalid payment/);
    }
    assert.equal(ledger.entries.length, 0);
    assert.equal(acks, 0);
  }

  // Valid boundary attempts values are accepted.
  {
    const ledger = new Ledger();
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    await service.pay('t', 'k1', 1, 1);
    await service.pay('t', 'k2', 1, 5);
    assert.equal(ledger.entries.length, 2);
  }

  // Direct Ledger.apply is idempotent and conflicting.
  {
    const ledger = new Ledger();
    const r1 = await ledger.apply('t', 'k', 10);
    const r2 = await ledger.apply('t', 'k', 10);
    assert.equal(r1, r2);
    assert.equal(ledger.entries.length, 1);
    await rejectsWith(() => ledger.apply('t', 'k', 11), /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }

  console.log('checks/verify.cjs: all checks passed');
}

module.exports = main();
EOF
